/* ---------- state ---------- */
const store={get:(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},set:(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{}}};
let cart=store.get('cheqbuy-cart',[]),wish=store.get('cheqbuy-wish',[]),cur=store.get('cheqbuy-currency','KES');
const CUR={KES:[1,'KES '],USD:[.0077,'$'],EUR:[.0071,'€'],GBP:[.0061,'£'],UGX:[28.6,'UGX '],TZS:[20.9,'TZS '],ZAR:[.14,'R '],NGN:[12.4,'NGN '],AED:[.028,'AED '],INR:[.67,'₹ ']};
const money=(k,c=cur)=>{const[r,p]=CUR[c],d=['KES','UGX','TZS','NGN'].includes(c)?0:2;return p+(k*r).toLocaleString('en-KE',{minimumFractionDigits:d,maximumFractionDigits:d})};
const timers=[];const every=(f,ms)=>{if(!RM)timers.push(setInterval(f,ms))};
const toast=(t,d='')=>{const e=$('#toast');e.innerHTML=`<b>${t}</b><div style="font-size:13px;color:var(--tx2)">${d}</div>`;e.classList.add('o');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove('o'),4000)};
const saveCart=()=>{store.set('cheqbuy-cart',cart);drawCart()};
const add=(id,q=1)=>{const p=P.find(x=>x.id===id),c=cart.find(x=>x.id===id);c?c.q+=q:cart.push({id,q});saveCart();toast('Added to cart',`${p.name} is in your cart.`)};
const total=()=>cart.reduce((s,c)=>s+P.find(p=>p.id===c.id).price*c.q,0);
function drawCart(){const n=cart.reduce((s,c)=>s+c.q,0),b=$('#cnt');b.hidden=!n;b.textContent=n;$('#cartBtn').setAttribute('aria-label','Open cart'+(n?`, ${n} items`:''));
 $('#cbody').innerHTML=cart.length?cart.map(c=>{const p=P.find(x=>x.id===c.id);return`<div class="ci"><img src="${p.img}" alt="${p.name}"><div style="flex:1;min-width:0"><b style="font-size:14px;display:block">${p.name}</b><small style="color:var(--tx2)">${p.sup}</small><div style="display:flex;align-items:center;gap:8px;margin-top:8px"><span class="qty"><button data-q="${p.id}:-1" aria-label="Decrease">−</button><span>${c.q}</span><button data-q="${p.id}:1" aria-label="Increase">+</button></span><b style="flex:1;text-align:right;font-size:14px">${money(p.price*c.q,'KES')}</b><button class="qty" style="border:0;cursor:pointer;background:none" data-rm="${p.id}" aria-label="Remove ${p.name}">🗑</button></div></div></div>`}).join(''):`<div style="text-align:center;padding:50px 10px"><div style="font-size:42px">🛒</div><b>Your cart is empty</b><p class="sub" style="margin:8px auto 18px">Add products from the marketplace and we will work the freight, duty and delivery into your order.</p><a class="orb gh sm" href="#/shop" data-close>Browse the marketplace</a></div>`;
 $('#cfoot').hidden=!cart.length;$('#cfoot').innerHTML=`<div style="display:flex;justify-content:space-between"><span>Goods subtotal</span><b style="font-size:18px">${money(total(),'KES')}</b></div><p style="font-size:12px;color:var(--tx2);margin:6px 0 14px">Freight, duty and delivery are quoted on the next step — no hidden charges.</p><button class="orb" style="width:100%" id="checkout">Proceed to checkout</button>`}
$('#cbody').onclick=e=>{const q=e.target.closest('[data-q]'),r=e.target.closest('[data-rm]');if(q){const[i,d]=q.dataset.q.split(':'),c=cart.find(x=>x.id===i);c.q=Math.max(1,c.q+ +d);saveCart()}if(r){cart=cart.filter(x=>x.id!==r.dataset.rm);saveCart()}if(e.target.closest('[data-close]'))closeAll()};
$('#cfoot').onclick=e=>{if(e.target.id==='checkout'){const l=cart.map(c=>`${c.q} x ${P.find(p=>p.id===c.id).name}`).join(', ');closeAll();location.hash='#/contact?msg='+encodeURIComponent('Order enquiry: '+l)}};

/* ---------- overlays ---------- */
const closeAll=()=>{['#menu','#cart','#ov'].forEach(s=>$(s).classList.remove('o'));document.body.style.overflow='';$('#menuBtn').setAttribute('aria-expanded','false')};
const open=s=>{closeAll();$(s).classList.add('o');$('#ov').classList.add('o');document.body.style.overflow='hidden';if(s==='#menu')$('#menuBtn').setAttribute('aria-expanded','true')};
$('#menuBtn').onclick=()=>open('#menu');$('#cartBtn').onclick=()=>open('#cart');$('#closeMenu').onclick=$('#closeCart').onclick=$('#ov').onclick=closeAll;
addEventListener('keydown',e=>e.key==='Escape'&&closeAll());
addEventListener('scroll',()=>$('#hd').classList.toggle('sc',scrollY>12),{passive:true});
const NAV=[['Home','#/'],['Services','#/services'],['Shop','#/shop'],['Track','#/track'],['Calculator','#/calculator'],['About','#/about'],['Contact','#/contact']];
