pages.shop=(q)=>{const cats=[...new Set(P.map(p=>p.cat))];return`${hero('Marketplace','Import what you sell, with the shipping already sorted','Every listing shows the supplier, the country of origin and the price in your currency — know the landed cost before you enquire.')}
<section class="wrap" style="padding-bottom:80px"><div class="bar"><input id="q" type="search" placeholder="Search products, HS codes, suppliers…" aria-label="Search products, HS codes or suppliers"><select id="cat" aria-label="Category"><option value="">All categories</option>${cats.map(c=>`<option>${c}</option>`).join('')}</select><select id="so" aria-label="Sort"><option value="">Featured first</option><option value="a">Price: low to high</option><option value="d">Price: high to low</option><option value="n">Name A–Z</option></select><select id="cu" aria-label="Currency">${Object.keys(CUR).map(c=>`<option ${c===cur?'selected':''}>${c}</option>`).join('')}</select></div>
<div class="chips" id="chips"></div><p style="margin-top:28px" id="rc" aria-live="polite"></p><div class="grid g4 sc3" id="pg" style="margin-top:16px"></div></section>`};
pages.shopInit=(q)=>{const st={q:'',c:q.get('category')||'',s:''};$('#cat').value=st.c;
 const draw=()=>{const t=st.q.toLowerCase();let l=P.filter(p=>(!st.c||p.cat===st.c)&&(!t||[p.name,p.sup,p.cat,p.origin].join(' ').toLowerCase().includes(t)));
  if(st.s==='a')l.sort((a,b)=>a.price-b.price);if(st.s==='d')l.sort((a,b)=>b.price-a.price);if(st.s==='n')l.sort((a,b)=>a.name.localeCompare(b.name));if(!st.s)l.sort((a,b)=>b.best-a.best);
  $('#chips').innerHTML=['All',...new Set(P.map(p=>p.cat))].map(c=>`<button class="chip2 ${(c==='All'&&!st.c)||c===st.c?'on':''}" data-c="${c}">${c}</button>`).join('');
  $('#rc').innerHTML=`<b>${l.length}</b> ${l.length===1?'listing':'listings'}${st.c?' in '+st.c:''}${st.c||st.q?' <a href="#/shop" style="color:var(--pri);text-decoration:underline;float:right">Clear filters</a>':''}`;
  $('#pg').innerHTML=l.length?l.map(card).join(''):`<div class="card" style="grid-column:1/-1;text-align:center;padding:56px"><h3>No listings match that search</h3><p class="sub" style="margin:10px auto 20px">Try a different keyword, or send us the product and we will source and quote it for you.</p><a class="orb sm" href="#/contact">Request sourcing</a></div>`;enhance($('#pg'))};
 $('#q').oninput=e=>{st.q=e.target.value;draw()};$('#cat').onchange=e=>{st.c=e.target.value;draw()};$('#so').onchange=e=>{st.s=e.target.value;draw()};$('#cu').onchange=e=>{cur=e.target.value;store.set('cheqbuy-currency',cur);draw()};
 $('#chips').onclick=e=>{const b=e.target.closest('[data-c]');if(b){st.c=b.dataset.c==='All'||st.c===b.dataset.c?'':b.dataset.c;$('#cat').value=st.c;draw()}};draw()};

pages.product=id=>{const p=P.find(x=>x.id===id);if(!p)return`${hero('Not found','We could not find that product','It may have been removed from the marketplace, or the link may be incorrect.','<a class="orb lt" href="#/shop">Browse the marketplace</a>')}`;
 const r=RATES[p.origin==='China'?'China':p.origin==='India'?'India':p.origin==='Turkey'?'Europe':'Within Africa'],w=p.cat==='Machinery'?40:p.cat==='Electronics'?1:5;
 return`<section class="wrap" style="padding-top:170px"><a href="#/shop" style="color:var(--tx2);font-size:14px">‹ Back to marketplace</a><div class="grid sc3" style="grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:40px;margin-top:24px"><div class="card tilt" data-tilt style="overflow:hidden"><img src="${p.img}" alt="${p.name}" style="width:100%;aspect-ratio:1;object-fit:cover"></div>
<div><div style="display:flex;gap:8px;flex-wrap:wrap"><span class="tag">${p.ver?'✔ Verified supplier':'Supplier'}</span><span class="tag" style="background:var(--mu);color:var(--tx2)">From ${p.origin}</span><span class="tag" style="background:var(--mu);color:var(--tx2)">${p.cat}</span></div><h1 style="font-size:clamp(1.9rem,4vw,2.4rem);font-weight:800;margin:6px 0">${p.name}</h1><p style="color:var(--tx2);font-size:14px">${p.sup}</p><div style="margin:14px 0"><span class="pr" style="font-size:30px;font-weight:800">${money(p.price)}</span>${p.old?`<span class="off">-${Math.round((1-p.price/p.old)*100)}%</span><span class="old">${money(p.old)}</span>`:''}</div>
<div class="card" style="padding:20px;background:rgba(89,175,191,.1);box-shadow:none;margin:22px 0"><b>${I.truck} Estimated shipping from ${p.origin}</b><div class="row" style="margin-top:12px;font-size:14px"><div>Air · ${r[1]} days<br><b>${money(w*r[0]*129,'KES')}</b></div><div>Sea · from<br><b>${money(r[3]*129,'KES')}</b></div><div>Typical sea transit<br><b>${r[4]} days</b></div></div><small style="color:var(--tx2)">Indicative, based on ${w} kg. Duty and VAT are quoted separately.</small></div>
<div class="btns"><span class="qty"><button id="m" aria-label="Decrease">−</button><b id="qn" style="min-width:24px;text-align:center">1</b><button id="pl" aria-label="Increase">+</button></span><button class="orb lt" id="ad">Add to cart</button><a class="orb gh" href="#/contact?msg=${encodeURIComponent('Quote request: '+p.name)}">Request a quote</a><a class="orb ol" href="#/calculator">Calculate shipping cost</a></div>
<p style="margin-top:26px;padding-top:20px;border-top:1px solid var(--bd);font-size:12px;color:var(--tx2)">${I.shield} Payment held until inspection passes · Pre-shipment inspection included</p></div></div>
<h2 style="font-size:1.8rem;margin-top:70px">More in ${p.cat}</h2><div class="grid g4 sc3">${P.filter(x=>x.cat===p.cat&&x.id!==p.id).slice(0,4).map(card).join('')}</div></section>`};
pages.productInit=id=>{let n=1;$('#m').onclick=()=>$('#qn').textContent=n=Math.max(1,n-1);$('#pl').onclick=()=>$('#qn').textContent=++n;$('#ad').onclick=()=>add(id,n)};

pages.about=()=>{const sc=[['app-splash','Welcome'],['app-ob1','Verified suppliers'],['app-home2','Home'],['app-ob3','Track every shipment'],['app-more','More services'],['app-login','Secure login']];return`${hero('About us','Connecting Africa to global markets','CheQBuy African Trade is a trade platform and freight partner for African businesses — import, export and ship with verified suppliers, transparent landed costs and live tracking, on the web and in the app.','<a class="orb lt" href="#/contact">Request a service</a><a class="orb gh" href="#/shop">Browse the marketplace</a>',['d51c85819_generated_ca7e32ef.png','357a5753b_generated_85a07b07.png','0a0cc131d_generated_e95f2c85.png','8ae3d8055_generated_1d1c240c.png'])}
<section class="sec wrap"><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:40px;margin-top:0;align-items:center"><div><span class="tag">What is CheQBuy?</span><h2>One partner from the factory floor to your door</h2><p class="sub">African businesses lose money to supply chains they cannot see: a supplier who takes a deposit and disappears, a container stuck at port, a duty bill higher than the quote.</p><p class="sub">CheQBuy removes that uncertainty. We vet suppliers, quote the full landed cost in writing, consolidate cargo, clear customs properly and deliver to your door — with every step visible in one tracking timeline.</p><p class="sub">We work both directions: bringing electronics, machinery and raw materials into Africa, and moving coffee, tea, textiles and agricultural produce out to buyers worldwide.</p></div>
<div class="grid sc3" style="margin-top:0;gap:16px">${[['Import','Shop verified suppliers in China, India, the UAE and Europe, with the landed cost shown up front.'],['Export','Send African produce and goods to buyers worldwide with the paperwork handled.'],['Ship','Air, sea and door-to-door options with clear per-kg pricing and live tracking.']].map(c=>`<div class="card tilt rv" data-tilt style="padding:22px"><h3 style="font-size:18px">${c[0]}</h3><p style="color:var(--tx2);font-size:14px;margin-top:6px">${c[1]}</p></div>`).join('')}</div></div></section>
<section class="sec navy" style="background:linear-gradient(135deg,#0B2436,#04414E)"><div class="blob" style="background:#59AFBF;left:-80px;top:0"></div><div class="wrap" style="position:relative"><span class="tag" style="background:rgba(255,255,255,.1);color:#59AFBF">The CheQBuy app</span><h2>Shop, ship and track from your phone</h2><p class="sub" style="color:rgba(255,255,255,.7)">Browse verified suppliers, compare air and sea rates by weight, and follow each parcel from pickup to delivery.</p>
<div class="cfw" style="margin-top:30px"><div class="cf" style="height:480px" tabindex="0" aria-label="App screens">${sc.map((x,i)=>`<figure class="cfc cfp" data-i="${i}"><img src="img/${x[0]}.jpg" alt="CheQBuy app — ${x[1]}"><figcaption>${x[1]}</figcaption></figure>`).join('')}</div><div class="cfn"><button class="orb gh ico" id="cp" aria-label="Previous screen">‹</button><span id="cd2" class="cdots">${sc.map((_,i)=>`<i data-d="${i}"></i>`).join('')}</span><button class="orb gh ico" id="cn" aria-label="Next screen">›</button></div></div><div style="margin-top:40px">${badges()}</div></div></section>
<section class="sec wrap"><span class="tag">Our values</span><h2>How we work when nobody is watching</h2><div class="grid g3 sc3">${[['Nothing hidden','Duty, freight and delivery in one written quote.'],['Verify before you pay','Supplier vetting and pre-shipment inspection are standard.'],['Clear it properly','We classify, declare and document correctly — no shortcuts.'],['Built for real traders','From one carton to a forty-foot container, with the same tracking.']].map(v=>`<div class="card tilt rv" data-tilt style="padding:24px"><span class="orb ico">${I.check}</span><h3 style="font-size:18px;margin-top:14px">${v[0]}</h3><p style="color:var(--tx2);font-size:14px;margin-top:6px">${v[1]}</p></div>`).join('')}</div></section>${cta}`};
pages.services=()=>`${hero('Services','Every way to move goods, quoted up front','Five services, one reference number and one team. Choose the mode that fits your goods, budget and deadline.','<a class="orb lt" href="#/contact">Request a service</a><a class="orb gh" href="#/calculator">Calculate shipping cost</a>')}
<section class="wrap" style="padding-bottom:80px;display:grid;gap:24px;margin-top:-20px">${SVC.map(s=>`<div class="card svc rv" id="${s[0]}" style="scroll-margin-top:120px"><img src="${B+s[6]}" alt="${s[1]} — ${s[2]}"><div><span class="tag">⏱ ${s[3]}</span><h2 style="font-size:2rem">${s[1]}</h2><ul style="margin-top:14px">${s[4].map(i=>`<li>${i}</li>`).join('')}</ul><div class="btns"><a class="orb sm" href="#/contact?msg=${encodeURIComponent('Service request: '+s[1])}">Request this service</a><a class="orb gh sm" href="#/calculator">See shipping rates</a></div></div></div>`).join('')}</section>${cta}`;

pages.track=()=>`${hero('Track shipment','Follow every milestone, from pickup to signature','Enter the reference we sent you, or the tracking number from your booking confirmation.','')}
<section class="wrap" style="max-width:960px;padding-bottom:80px"><form class="card f" id="tf" style="padding:18px;margin-top:-30px;grid-template-columns:1fr auto"><input id="tn" placeholder="e.g. CQB-482913" aria-label="Tracking number" required><button class="orb lt">Track shipment</button></form><p style="font-size:13px;color:var(--tx2);margin:10px 4px">Trying it out? <button id="demo" style="background:none;border:0;color:var(--pri);text-decoration:underline;cursor:pointer">Use demo number CQB-482913</button></p><div id="tr" aria-live="polite" style="margin-top:20px"></div></section>`;
pages.trackInit=()=>{const go=v=>{v=v.trim().toUpperCase();const o=$('#tr');if(v!==DEMO.n){o.innerHTML=`<div class="card" style="padding:40px;text-align:center"><h3>No shipment found for “${v.replace(/[<>&]/g,'')}”</h3><p class="sub" style="margin:10px auto">Check the spelling of the reference, or send it to our trade desk and we will look it up for you.</p></div>`;return}
 const f=d=>new Date(d).toLocaleString('en-KE',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
 o.innerHTML=`<div class="card" style="padding:24px;display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px"><div><small style="color:var(--tx2)">Tracking number</small><h3 style="font-size:24px">${DEMO.n}</h3><p style="font-size:14px;color:var(--tx2)">${DEMO.svc} · ${DEMO.route} · ${DEMO.w} kg</p></div><div><span class="st" style="background:rgba(76,175,80,.15);color:var(--ok)">Delivered</span> <span class="st" style="background:rgba(255,152,0,.15);color:var(--wn)">Demo shipment</span></div></div><ol class="tm" style="margin-top:24px">${DEMO.ev.map((e,i)=>`<li class="on ${i==4?'cur':''}"><span class="d">${I.check}</span><div class="c card" style="box-shadow:none"><b>${e[0]}</b> <small style="color:var(--tx2);float:right">${f(e[2])}</small><div style="font-size:13px;color:var(--tx2)">${e[1]}</div><div style="font-size:13px">${e[3]}</div></div></li>`).join('')}</ol>`};
 $('#tf').onsubmit=e=>{e.preventDefault();go($('#tn').value)};$('#demo').onclick=()=>{$('#tn').value=DEMO.n;go(DEMO.n)}};

pages.calculator=()=>`${hero('Cost calculator','Know the landed cost before you commit','Pick a mode and origin, enter the weight and value, and watch freight, duty and VAT update live.')}
<section class="wrap" style="padding-bottom:80px"><div class="grid sc3" style="grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));margin-top:-30px"><div class="card f" style="padding:28px"><label>Shipping mode<select id="cm"><option value="air">Air freight — fastest, per kilo</option><option value="sea">Sea freight — best for volume</option><option value="door">Door-to-door — collection and delivery</option></select></label><label>Shipping from<select id="co">${Object.keys(RATES).map(o=>`<option>${o}</option>`).join('')}</select></label><label>Weight — <span id="wv">120</span> kg<input type="range" id="cw" min="1" max="5000" value="120"></label><div class="row"><label>Volume (cbm)<input id="cv" type="number" value="2" step=".1" min="0"></label><label>Goods value (KES)<input id="cg" type="number" value="500000" step="1000" min="0"></label></div><label>Import duty — <span id="dv">25</span>%<input type="range" id="cd" min="0" max="35" value="25"></label></div>
<div class="card" style="overflow:hidden;align-self:start;position:sticky;top:90px"><div style="background:linear-gradient(135deg,#016072,#0B2436);color:#fff;padding:24px"><small style="color:#59AFBF">Estimated landed cost</small><div style="font-size:34px;font-weight:800" id="rt">—</div><small id="rs" style="opacity:.7"></small></div><div id="rb" style="padding:8px 24px 20px"></div><div style="padding:0 24px 24px"><a class="orb lt" style="width:100%" href="#/contact">Request this shipment</a><p style="font-size:12px;color:var(--tx2);margin-top:10px">Indicative estimate, not a quotation. Final pricing depends on chargeable weight and commodity.</p></div></div></div></section>`;
pages.calcInit=()=>{const u=()=>{const m=$('#cm').value,o=RATES[$('#co').value],kg=+$('#cw').value,cb=+$('#cv').value,v=+$('#cg').value,d=+$('#cd').value;$('#wv').textContent=kg;$('#dv').textContent=d;
 let fr=m==='air'?kg*o[0]:m==='sea'?Math.max(cb*o[2],o[3]):kg*(o[0]+1.1);fr+=60;const fk=fr*129,du=v*d/100,vat=(v+fk+du)*.16,t=fk+du+vat;
 $('#rt').textContent=money(t,'KES');$('#rs').textContent=`${$('#co').value} → Nairobi · ${m==='sea'?o[4]:o[1]} days`;
 $('#rb').innerHTML=[['Freight',fk],['Handling and documentation',60*129],[`Import duty (${d}%)`,du],['VAT (16%)',vat]].map(r=>`<div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--bd);font-size:14px"><span>${r[0]}</span><b>${money(r[1],'KES')}</b></div>`).join('')+`<div style="display:flex;justify-content:space-between;padding:12px 0;font-weight:800"><span>Total estimate</span><span>${money(t,'KES')}</span></div>`};
 $$('#cm,#co,#cw,#cv,#cg,#cd').forEach(e=>e.oninput=u);u()};

pages.contact=q=>`${hero('Contact','Talk to a human who knows the route','Nairobi head office, Mombasa warehouse and a representative office in Guangzhou. We reply within four working hours.',`<a class="orb lt" href="https://wa.me/254136854991" target="_blank" rel="noopener">Chat on WhatsApp</a><a class="orb gh" href="mailto:${MAIL}">${MAIL}</a><a class="orb ol" style="color:#fff;box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.4)" href="tel:+254136854991">${PHONE}</a>`)}
<section class="wrap" style="padding-bottom:80px"><div class="grid sc3" style="grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));margin-top:-30px"><form class="card f" id="cf" style="padding:28px" novalidate><h2 style="font-size:1.7rem">Send us a message</h2><label>Your name*<input name="n" required></label><label>Email address*<input name="e" type="email" required></label><label>What is this about?<select><option>General enquiry</option><option>Request a quote</option><option>Track a shipment</option><option>Customs and clearance</option><option>Sourcing a product</option></select></label><label>Message*<textarea name="m" rows="5" required placeholder="e.g. I need to ship 400 kg of phone accessories from Guangzhou to Mombasa.">${(q.get('msg')||'').replace(/[<>]/g,'')}</textarea></label><p id="er" role="alert" style="color:var(--er);font-size:13px"></p><button class="orb lt">Send message</button></form>
<div style="display:grid;gap:20px;align-content:start"><div class="card" style="padding:24px"><h3>Visit the head office</h3><p style="color:var(--tx2);margin:6px 0 14px">CheQBuy House, Mombasa Road, Nairobi, Kenya</p><a class="orb gh sm" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=Mombasa+Road+Nairobi+Kenya">${I.pin} Open in Google Maps</a></div><div class="card" style="padding:24px"><h3>Opening hours</h3><p style="font-size:14px;color:var(--tx2)">Mon–Fri 08:00 – 18:00 EAT<br>Saturday 09:00 – 14:00 EAT<br>Sunday: urgent shipments only</p></div><div class="card" style="padding:24px"><h3>Reach us</h3><p style="font-size:14px;color:var(--tx2)"><a href="tel:+254136854991">${PHONE}</a><br><a href="mailto:${MAIL}">${MAIL}</a></p></div></div></div></section>`;
pages.contactInit=()=>{$('#cf').onsubmit=e=>{e.preventDefault();const f=e.target;if(!f.n.value.trim())return $('#er').textContent='Please tell us your name.';if(!/^\S+@\S+\.\S+$/.test(f.e.value))return $('#er').textContent='Enter a valid email address, e.g. name@company.com';if(f.m.value.trim().length<10)return $('#er').textContent='Please add a little more detail so we can help.';
 location.href=`mailto:${MAIL}?subject=${encodeURIComponent('CheQBuy enquiry from '+f.n.value)}&body=${encodeURIComponent(f.m.value+'\n\n'+f.n.value+' · '+f.e.value)}`;f.outerHTML=`<div class="card" style="padding:40px"><h2 style="font-size:1.7rem">Message ready</h2><p class="sub">Your email app has opened with the message. For anything urgent, call ${PHONE}.</p></div>`}};

/* ---------- enhancements ---------- */
function enhance(r=document){$$('[data-tilt]',r).forEach(c=>{if(c._t||RM)return;c._t=1;c.onmousemove=e=>{const b=c.getBoundingClientRect(),x=(e.clientX-b.left)/b.width-.5,y=(e.clientY-b.top)/b.height-.5;c.style.transform=`perspective(1000px) rotateY(${x*6}deg) rotateX(${-y*6}deg) translateY(-10px)`};c.onmouseleave=()=>c.style.transform='perspective(1000px)'});
 const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.2});$$('.rv',r).forEach(e=>RM?e.classList.add('in'):io.observe(e));
 $$('[data-n]',r).forEach(el=>{const t=+el.dataset.n,s=el.dataset.s,fmt=v=>(t%1?v.toFixed(1):Math.round(v).toLocaleString('en-KE'))+s;if(RM)return el.textContent=fmt(t);const o=new IntersectionObserver(([e])=>{if(!e.isIntersecting)return;o.disconnect();const t0=performance.now(),st=n=>{const k=Math.min(1,(n-t0)/1500);el.textContent=fmt(t*(1-Math.pow(1-k,3)));k<1&&requestAnimationFrame(st)};requestAnimationFrame(st)},{threshold:.5});o.observe(el)})}
function globe(){const cv=$('#gl');if(!cv||!window.THREE)return;const T=THREE,r=new T.WebGLRenderer({canvas:cv,alpha:true,antialias:true}),s=new T.Scene(),cam=new T.PerspectiveCamera(40,1,.1,50);cam.position.set(0,.15,5.15);r.setPixelRatio(Math.min(2,devicePixelRatio));
 const g=new T.Group();g.rotation.set(.22,-1.15,0);s.add(g);const R=1.62;
 g.add(new T.Mesh(new T.SphereGeometry(R,64,64),new T.MeshPhongMaterial({color:0x0d2b3d,emissive:0x06202b,shininess:42,specular:0x59AFBF})));
 g.add(new T.Mesh(new T.SphereGeometry(R+.004,42,28),new T.MeshBasicMaterial({color:0x59AFBF,wireframe:true,transparent:true,opacity:.3})));
 g.add(new T.Mesh(new T.SphereGeometry(R+.16,48,48),new T.MeshBasicMaterial({color:0x59AFBF,transparent:true,opacity:.07,side:T.BackSide})));
 const C={Nairobi:[-1.29,36.82],Mombasa:[-4.04,39.66],Durban:[-29.85,31.02],Lagos:[6.52,3.37],Cairo:[30.04,31.24],Guangzhou:[23.13,113.26],Dubai:[25.2,55.27],Mumbai:[19.07,72.87],London:[51.51,-.13],Rotterdam:[51.92,4.48],'New York':[40.71,-74.01],'Dar es Salaam':[-6.79,39.21]};
 const v=(la,lo,k=1)=>{const p=(90-la)*Math.PI/180,t=(lo+180)*Math.PI/180;return new T.Vector3(-R*k*Math.sin(p)*Math.cos(t),R*k*Math.cos(p),R*k*Math.sin(p)*Math.sin(t))};
 g.add(new T.Points(new T.BufferGeometry().setFromPoints(Object.values(C).map(c=>v(...c))),new T.PointsMaterial({color:0x9ff5ef,size:.05})));
 const mk=[];[['Nairobi','Guangzhou',0x59AFBF],['Mombasa','Dubai',0xFF9800],['Lagos','London',0x59AFBF],['Durban','Rotterdam',0x7fd0dc],['Nairobi','Mumbai',0xFF9800],['Cairo','New York',0x59AFBF]].forEach((a,i)=>{const A=v(...C[a[0]]),Z=v(...C[a[1]]),M=A.clone().add(Z).multiplyScalar(.5).normalize().multiplyScalar(R*1.42),cu=new T.QuadraticBezierCurve3(A,M,Z);
  g.add(new T.Mesh(new T.TubeGeometry(cu,48,.0075,6),new T.MeshBasicMaterial({color:a[2],transparent:true,opacity:.72})));
  const m=new T.Mesh(i%2?new T.BoxGeometry(.055,.032,.1):new T.ConeGeometry(.032,.1,12),new T.MeshBasicMaterial({color:i%2?0xFF9800:0xffffff}));g.add(m);mk.push([m,cu,i*.17])});
 s.add(new T.AmbientLight(0x35506b,1.35));const d=new T.DirectionalLight(0xffffff,1.5);d.position.set(4,5,6);s.add(d);const pl=new T.PointLight(0x59AFBF,2.6,14);pl.position.set(-3.4,-2,3.2);s.add(pl);
 const ptr={x:0,y:0,tx:0,ty:0};if(!RM)addEventListener('mousemove',e=>{ptr.tx=(e.clientX/innerWidth-.5)*.55;ptr.ty=(e.clientY/innerHeight-.5)*.35});
 const rs=()=>{const w=cv.clientWidth||400;r.setSize(w,w,false);cam.aspect=1;cam.updateProjectionMatrix()};new ResizeObserver(rs).observe(cv.parentElement);rs();let t=0,run=true;
 const L=()=>{if(!$('#gl'))return;requestAnimationFrame(L);if(!RM){t+=.0016;g.rotation.y+=.0016;ptr.x+=(ptr.tx-ptr.x)*.05;ptr.y+=(ptr.ty-ptr.y)*.05;cam.position.x=ptr.x*1.5;cam.position.y=.15-ptr.y*.9;g.rotation.z=ptr.y*.16}
  mk.forEach(([m,cu,o])=>{const k=(o+(performance.now()/1000)*.055)%1,p=cu.getPoint(k);m.position.copy(p);m.lookAt(g.localToWorld(p.clone().multiplyScalar(2)))});cam.lookAt(0,0,0);r.render(s,cam)};L()}
