 const lay=()=>{cs.forEach((c,i)=>{let d=i-a;if(d>n/2)d-=n;if(d<-n/2)d+=n;const x=Math.abs(d);c.style.transform=`translate(-50%,-50%) translateX(${d*54}%) translateZ(${-x*80}px) rotateY(${d*-28}deg) scale(${1-x*.05})`;c.style.zIndex=30-x;c.style.opacity=x>2?0:1-x*.16;c.style.pointerEvents=x>2?'none':'auto';c.classList.toggle('act',!d)});dt.forEach((e,i)=>e.classList.toggle('a',i===a))},go=k=>{a=(k+n)%n;lay()};
