/* ---------- router ---------- */
function route(){timers.splice(0).forEach(clearInterval);closeAll();const raw=location.hash.slice(1)||'/',[full,anchor]=raw.split('#'),[path,qs]=full.split('?'),q=new URLSearchParams(qs||''),seg=path.split('/').filter(Boolean),app=$('#app');
 let html,init,title='CheQBuy African Trade';
 if(!seg.length){html=pages.home()}else if(seg[0]==='shop'&&seg[1]){const p=P.find(x=>x.id===seg[1]);html=pages.product(seg[1]);init=()=>p&&pages.productInit(seg[1]);title=p?p.name:title}
 else if(seg[0]==='shop'){html=pages.shop(q);init=()=>pages.shopInit(q);title='Marketplace'}
 else if(pages[seg[0]]){html=pages[seg[0]](q);init=pages[seg[0]==='calculator'?'calcInit':seg[0]+'Init'];title=seg[0][0].toUpperCase()+seg[0].slice(1)}
 else html=`<section class="wrap" style="padding:170px 20px;text-align:center"><span class="tag">404</span><h1 style="font-size:2.6rem;font-weight:800">This page took a wrong turn</h1><p class="sub" style="margin:14px auto 28px">The page you are looking for has moved, or the link is incorrect.</p><div class="btns" style="justify-content:center"><a class="orb" href="#/">Back to home</a><a class="orb gh" href="#/shop">Browse the marketplace</a></div></section>`;
 app.innerHTML=html;document.title=title==='CheQBuy African Trade'?title+' — Import · Export · Ship across Africa and the world':title+' | CheQBuy African Trade';
 const cur=seg.length?'#/'+seg[0]:'#/';$('#links').innerHTML=NAV.map(n=>`<a href="${n[1]}" class="${n[1]===cur?'on':''}" ${n[1]===cur?'aria-current="page"':''}>${n[0]}</a>`).join('');$('#strip').innerHTML=NAV.map(n=>`<a href="${n[1]}" class="${n[1]===cur?'on':''}">${n[0]}</a>`).join('');
 $('#mlinks').innerHTML=NAV.map(n=>`<a href="${n[1]}" class="${n[1]===cur?'on':''}">${n[0]}</a>`).join('');
 init&&init();enhance(app);if(!seg.length){heroInit();showcase();phone3d();coverflow();phones()}if(seg[0]==='about'){coverflow();aboutHero()}
 if(!RM)app.animate([{opacity:0,transform:'perspective(1400px) rotateX(9deg) translateY(36px)'},{opacity:1,transform:'none'}],{duration:750,easing:'cubic-bezier(.22,1,.36,1)'});
 anchor?setTimeout(()=>($('#'+anchor)||{scrollIntoView(){}}).scrollIntoView({behavior:RM?'auto':'smooth'}),140):scrollTo(0,0)}
addEventListener('hashchange',route);drawCart();route();

